import 'package:flutter/material.dart';import 'package:provider/provider.dart';import 'package:your_app_name/providers/app_provider.dart';import 'package:your_app_name/screens/detail_screen.dart';class HomeScreen extends StatelessWidget {  const HomeScreen({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    final appProvider = Provider.of<AppProvider>(context);    final appModels = appProvider.appModels;    return Scaffold(      appBar: AppBar(        title: const Text('Home Screen'),      ),      body: appModels.isEmpty          ? const Center(child: CircularProgressIndicator())          : ListView.builder(              itemCount: appModels.length,              itemBuilder: (context, index) {                return ListTile(                  title: Text(appModels[index].title),                  subtitle: Text(appModels[index].description),                  onTap: () {                    Navigator.push(                      context,                      MaterialPageRoute(                        builder: (context) => DetailScreen(appModel: appModels[index]),                      ),                    );                  },                );              },            ),    );  }}